.hero {
  position: relative;
  min-height: 100vh;
  background-color: var(--color-obsidian);
  color: var(--color-paper);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: var(--spacing-64) var(--spacing-28);
  text-align: center;
  overflow: hidden;
}

.hero-content {
  z-index: 2;
  max-width: var(--page-max-width);
  width: 100%;
  margin-bottom: var(--spacing-68);
}

.hero-title {
  font-family: var(--font-roobert);
  font-size: var(--text-display);
  color: var(--color-paper);
  font-weight: var(--font-weight-semibold);
  margin-bottom: var(--spacing-40);
}

.hero-subtitle {
  font-family: var(--font-raleway);
  font-size: var(--text-body-lg);
  color: var(--color-ash-mist);
  margin-bottom: var(--spacing-48);
}

.hero-buttons {
  display: flex;
  gap: var(--spacing-28);
  margin-bottom: var(--spacing-48);
}

.hero-button {
  font-family: var(--font-roobert);
  font-size: var(--text-body);
  color: var(--color-iridescent-fade);
  background: var(--color-iridescent-fade);
  border: none;
  padding: var(--spacing-12) var(--spacing-28);
  border-radius: var(--radius-buttons);
  cursor: pointer;
  transition: background 0.3s ease, color 0.3s ease;
}

.hero-button:hover {
  background: var(--gradient-iridescent-fade);
  color: var(--color-paper);
}

.hero-illustration {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 1;
  overflow: hidden;
}

.parallax-layer {
  position: relative;
  transform: translate3d(0, 0, 0);
  will-change: transform;
}

.parallax-image {
  width: 100%;
  height: auto;
  opacity: 0.6;
  transition: transform 0.5s ease-in-out;
}

.hero-illustration:hover .parallax-image {
  transform: scale(1.05);
}
</file>
</tool_call><|im_end|>
